-- ---------------------------------------------------------------------
-- 26 QCM
-- ---------------------------------------------------------------------
INSERT INTO challenges (title, type, selection_type, difficulty, context, question, code_snippet, code_language, explanation, estimated_time_seconds, active, points, created_at, updated_at)
SELECT v.title, v.type, v.selection_type, v.difficulty, v.context, v.question,
       NULLIF(v.snippet, ''), NULLIF(v.lang, ''), v.explanation, v.time, TRUE, v.points,
       CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM (VALUES
-- JUNIOR (7)
('SQL : ordre des colonnes d''un index composite', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'JUNIOR',
 'Un index existe sur (client_id, created_at). La requête la plus lente du service filtre sur created_at SEUL.',
 'Que dit le planificateur PostgreSQL et quelle indexation choisir ?',
 '',
 '',
 'Un index composite ne sert pas (ou mal) quand le préfixe client_id n''est pas filtré : la colonne de gauche est la clé d''accès. Créer un index sur created_at dédié, ou réfléchir aux requêtes réelles avant d''indexer — l''ordre des colonnes suit les prédicats.',
 120, 15),
('SQL : lignes dupliquées après un LEFT JOIN', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'JUNIOR',
 'Une page de commandes affiche chaque commande 3 fois depuis l''ajout d''une jointure vers les lignes de détail.',
 'Pourquoi les doublons apparaissent-ils et comment les éviter ?',
 '',
 '',
 'Une jointure 1:N duplique la ligne de gauche autant de fois qu''il y a d''enfants. Séparer les agrégats (GROUP BY/ sous-requête pour les totaux) de la liste principale, ou filtrer l''enfant côté droit avant jointure (sous-requête dédiée).',
 120, 15),
('SQL : COUNT(colonne) contre COUNT(*)', 'SITUATIONAL_QCM', 'MULTIPLE_CHOICE', 'JUNIOR',
 'Un tableau de bord affiche « 980 utilisateurs » alors que la table en contient 1000 : 20 e-mails sont vides.',
 'Quelles affirmations sont exactes ?',
 '',
 '',
 'COUNT(*) compte les lignes ; COUNT(colonne) compte les valeurs NON NULL de cette colonne. Les deux sont donc légitimes selon l''intention : lignes totales vs renseignés. Ni COUNT(DISTINCT col) ni COALESCE ne changent cette règle fondamentale.',
 90, 10),
('SQL : le filtre sur NULL ne filtre jamais', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'JUNIOR',
 'Un rapport utilise WHERE email = NULL pour trouver les comptes sans email. Il renvoie 0 ligne, pourtant il en existe.',
 'Quelle syntaxe cherche les valeurs nulles et pourquoi l''égalité échoue-t-elle ?',
 '',
 '',
 'NULL signifie « inconnu » : toute comparaison = ou <> renvoie UNKNOWN, donc jamais vraie. Il faut IS NULL / IS NOT NULL (ou COALESCE pour forcer une valeur). C''est le « trois-valued logic » du SQL.',
 90, 10),
('SQL : ORDER BY absent sur une pagination', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'JUNIOR',
 'Une liste paginée (LIMIT/OFFSET sans ORDER BY) affiche des éléments dans un ordre différent à chaque affichage.',
 'Quelle est la garantie SQL respectée ou non ici ?',
 '',
 '',
 'Sans ORDER BY, l''ordre de retour est AUCUNEMENT garanti (il dépend du plan, du parallélisme, des pages lues). Pagination stable = ORDER BY explicite sur une clé totale (id en dernier recours) — sinon les pages se chevauchent ou perdent des lignes.',
 90, 10),
('SQL : montants en DOUBLE PRECISION', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'JUNIOR',
 'Une table de paiements utilise DOUBLE PRECISION pour les montants. Les totaux diffèrent de 0,01 € de la référence comptable.',
 'Quelle est la cause et le type adapté ?',
 '',
 '',
 'Les flottants représentent les décimales en binaire : 0,1 n''est pas exact, l''accumulation diverge. Pour l''argent : NUMERIC/DECIMAL(p,s) — arithmétique décimale exacte, précision déclarée (ex. NUMERIC(12,2)).',
 90, 10),
('SQL : clé étrangère sans index', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'JUNIOR',
 'Supprimer un client de 50 000 commandes prend des secondes et bloque ; la FK orders.user_id n''a aucun index.',
 'Quel coût PostgreSQL doit-il payer et que faut-il faire ?',
 '',
 '',
 'À chaque écriture sur users, PostgreSQL doit vérifier l''absence d''enfants orphelins : sans index, c''est un SCAN de la table enfant par écriture. Indexer systématiquement les colonnes de clés étrangères (et le vérifier à la revue de schéma).',
 120, 15),
-- INTERMEDIATE (13)
('SQL : le planificateur choisit un seq scan', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Un index existe sur users(email), mais une requête unitaire fait un Seq Scan à 300 ms sur une table de 5 millions de lignes.',
 'Quelles explications sont plausibles et quelle est la vérification d''abord ?',
 '',
 '',
 'D''abord EXPLAIN (ANALYZE, BUFFERS) : un seq scan peut être CHOISI volontairement si la sélectivité est faible (beaucoup de lignes matchées) ou si les statistiques/filtres sont mal évalués. Ensuite seulement : ANALYZE, réécriture sargable, ou index partiel. Corriger à l''aveugle crée des index morts.',
 180, 20),
('SQL : niveaux d''isolation et lecture fantôme', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Un traitement relit un ensemble de lignes dans la même transaction et obtient un jeu différent : le compteur total diverge.',
 'Quel phénomène est en cause selon l''isolation et la solution ?',
 '',
 '',
 'Sous READ COMMITTED, chaque instruction voit l''état le plus récent : les fantômes (lignes ajoutées par autrui entre deux lectures) sont possibles. Pour un traitement qui doit voir un jeu stable : REPEATABLE READ (ou SERIALIZABLE), avec gestion des conflits de serialization.',
 180, 20),
('SQL : deadlock entre deux transactions', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'T1 verrouille la ligne A puis B ; T2 verrouille B puis A. Par intermittence : « deadlock detected ».',
 'Le remède structurel ?',
 '',
 '',
 'Aligner l''ordre d''acquisition des verrous (toujours même ordre de clés/tables), borner les transactions (le plus court possible) et retry borné. Le deadlock est détecté et annulé par PG — c''est la correction d''ordre qui élimine le phénomène.',
 120, 15),
('SQL : mise à jour globale sans ciblage', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Un UPDATE factures SET statut = ... sans WHERE est lancé en prod : la table est verrouillée ~40 s et les lectures se mettent en file.',
 'Quel problème PostgreSQL est à l''œuvre et quelle méthode préférer ?',
 '',
 '',
 'Chaque ligne modifiée est verrouillée (ROW EXCLUSIVE) et l''opération génère du WAL : sur des millions de lignes, c''est un verrouillage long, bloat et réplication ralentie. Traiter par lots (WHERE id IN / plage, boucle contrôlée) avec un délai entre les lots — idéalement hors période de charge.',
 180, 20),
('SQL : compteur concurrent et mise à jour perdue', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Deux transactions lisent nb = 12 puis écrivent nb = 13 : une incrémentation a disparu en production.',
 'Quel mécanisme de verrouillage corrige définitivement ce motif ?',
 '',
 '',
 'SELECT ... FOR UPDATE à la lecture (blocage de la ligne jusqu''à commit) ou une incrémentation atomique dans le SET (nb = nb + 1) sans relecture applicative. C''est le lost update classique : lire-modifier-écrire sans verrou.',
 180, 20),
('SQL : OFFSET profond sur une table chargée', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'La page « suivant » 40 000 d''un catalogue prend 1,8 s alors que la première est instantanée.',
 'Quelle technique de pagination reste rapide avec la profondeur ?',
 '',
 '',
 'La pagination par offset force PostgreSQL à compter et jeter les lignes précédentes (coût linéaire). Le keyset (WHERE (created_at, id) < (dernier_cree, dernier_id) ORDER BY created_at DESC, id DESC LIMIT n) ne parcourt que le segment utile : constant et reproducible.',
 180, 20),
('SQL : Bornes de date et BETWEEN', 'SITUATIONAL_QCM', 'MULTIPLE_CHOICE', 'INTERMEDIATE',
 'Un rapport mensuel utilise WHERE created_at BETWEEN TIMESTAMP "2024-01-31" ET TIMESTAMP "2024-01-31 23:59:59" — quelques lignes de minuit 00:00:00.5 manquent.',
 'Quelles affirmations sont exactes ?',
 '',
 '',
 'BETWEEN est inclusif des bornes mais ne couvre pas les fractions de seconde entre 23:59:59 et minuit. La forme robuste est une borne ouverte : created_at >= "2024-01-01" AND created_at < "2024-02-01" — sans jamais dépendre de la dernière seconde du jour.',
 120, 15),
('SQL : expression sur colonne = index ignoré', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'WHERE LOWER(email) = "x@y" scanne toute la table malgré un index sur email.',
 'Que faut-il comprendre et quelles solutions existent ?',
 '',
 '',
 'L''index est construit sur la valeur brute ; une fonction appliquée dans le WHERE rend la recherche non sargable. Solutions : index sur l''expression (CREATE INDEX ON users (LOWER(email))), colonne générée indexée, ou collation insensible si l''usage le justifie.',
 180, 20),
('SQL : motif LIKE et types d''index', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'La recherche produit "LIKE "%son%" est lente ; "LIKE "Dupont%" est instantanée.',
 'Pourquoi cette différence et que propose PostgreSQL ?',
 '',
 '',
 'Un préfixe ("Dupont%") est compatible avec un B-tree (ordre lexicographique exploitable). Une occurrence n''importe où exige un scan ou un index de trigrammes (pg_trgm) : l''index stocke les trigrammes et répond aux motifs contenant %.',
 120, 15),
('SQL : UNION contre UNION ALL', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Un report agrège deux jeux de données (1M + 300k lignes) avec UNION. Le temps est disproportionné alors qu''aucun doublon n''est attendu.',
 'Quelle cause et quel réglage ?',
 '',
 '',
 'UNION impose une étape de déduplication (tri/hash coûteux) ; UNION ALL concatène sans contrôle. Si la disjointure est garantie par construction (ou testée), UNION ALL évite le coût — sinon c''est UNION qui protège l''exactitude du résultat.',
 120, 15),
('SQL : cast implicite dans une jointure', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Une jointure orders.customer_id = c.external_ref (VARCHAR) fonctionne... mais le plan passe en séquentiel complet sur 8 M lignes.',
 'Pourquoi l''index de customer_id n''est plus exploitable et comment corriger ?',
 '',
 '',
 'Comparer BIGINT à VARCHAR impose une conversion : la fonction de conversion appliquée à la colonne empêche l''utilisation de l''index (et peut masquer des erreurs de format). Corriger le type à la source (colonne homogène) plutôt que de caster à la volée.',
 180, 20),
('SQL : sous-requête corrélée exécutée par ligne', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Une requête avec NOT IN (SELECT ...) met 6 s : EXPLAIN montre une boucle imbriquée réexécutée par ligne.',
 'Quelle réécriture maîtrise le plan ?',
 '',
 '',
 'Passer en JOIN (anti-join LEFT JOIN ... IS NULL ou NOT EXISTS avec alias propre). Attention : IN avec un jeu contenant NULL renvoie jamais TRUE (piege classique) — NOT EXISTS est souvent le plus sûr et le mieux planifié.',
 180, 20),
-- ADVANCED (6)
('SQL : upsert et course entre deux écritures', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Un import applicatif fait SELECT puis INSERT si absent : deux lots parallèles insèrent la même clé et l''un échoue en violation d''unicité.',
 'Quelle opération PostgreSQL gère nativement ce motif « insert si absent » ?',
 '',
 '',
 'INSERT ... ON CONFLICT (cle) DO UPDATE|NOTHING est ATOMIQUE côté base : le verrou de ligne gère la course, là où SELECT-then-INSERT laisse une fenêtre entre les deux étapes. À défaut, la contrainte d''unicité + gestion du conflit reste la dernière ligne de défense.',
 120, 15),
('SQL : plan dégradé après montée de volumétrie', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'ADVANCED',
 'Après passage de 2 à 80 millions de lignes, une requête passée de 40 ms à 4 s. Aucun index n''a changé.',
 'Quelle hypothèse investiguer en premier et quelle action ?',
 '',
 '',
 'Les statistiques (autovacuum/ANALYZE) et la sélectivité réelle : le planificateur peut basculer en seq scan ou choisir un mauvais join order faute de valeurs à jour (taille du travail, valeur de la colonne skewed). ANALYZE manuel/vacuum ajusté, puis comparer les plans (EXPLAIN (ANALYZE, BUFFERS)) — les hints ne viennent qu''en dernier recours.',
 240, 25),
('SQL : autovacuum ne suit plus la charge', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'ADVANCED',
 'La table events grossit de 2 M lignes/jour, les UPDATE sont fréquents : bloat, index gonflés, VACUUM manuels récurrents.',
 'Quel sous-système est débordé et quelles commandes/ajustements ?',
 '',
 '',
 'L''autovacuum ne récupère pas l''espace des dead tuples assez vite (seuils par défaut face au taux d''écriture) : bloat = scans plus longs, index plus hauts. Ajuster scale_factor/threshold par table, vérifier les longues transactions qui bloquent le vacuum (pg_stat_activity, xmin horizon), et VACUUM (FULL/REINDEX) en fenêtre dédiée si le bloat est installé.',
 240, 25),
('SQL : index BRIN sur une table temporelle', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'ADVANCED',
 'Une table logs de 400 M lignes est quasi ordonnée par timestamp (append-only). Le B-tree sur created_at fait 12 Go.',
 'Quelle indexation PostgreSQL réduit drastiquement la taille tout en servant les plages temporelles ?',
 '',
 '',
 'Un BRIN (Block Range INdex) ne stocke qu''un résumé par bloc de pages : quelques Mo pour des Tb, idéal quand la corrélation physique/valeur est forte (append-only trié). Si l''ordre n''est plus garanti, retour au B-tree — la pertinence dépend de la distribution physique réelle.',
 180, 20),
('SQL : partitionnement de table volume géant', 'SITUATIONAL_QCM', 'MULTIPLE_CHOICE', 'ADVANCED',
 'Une table de 1,5 Md de lignes (accès quasi toujours sur les 30 derniers jours) subit des DROP/PART maintenance de plus en plus lourds.',
 'Quels bénéfices le partitionnement apporte-t-il ici ?',
 '',
 '',
 'Partitionnement déclaratif par plage de dates : partitions détachables (DROP instantané des périodes mortes), partition pruning (le planner ne touche que les partitions pertinentes), maintenance locale. Le gain principal est opérationnel (maintenance/détachement) autant que performance — au prix de la complexité des clés/séquences.',
 240, 25),
('SQL : anomalies de sérialisation sous forte charge', 'SITUATIONAL_QCM', 'SINGLE_CHOICE', 'ADVANCED',
 'Une passerelle passe en SERIALIZABLE pour ses traitements financiers : sous pic, 2 % des transactions échouent en "could not serialize access".',
 'Comment traiter ces échecs dans l''application ?',
 '',
 '',
 'Un échec de sérialisation est NORMAL : il prouve l''isolation forte. Le correctif applicatif est un retry borné avec backoff (jusqu''à N essais), couplé à des transactions courtes. Sans retry, la contrainte se transforme en erreur utilisateur ; avec un retry infini, en charge inutile.',
 180, 20),
('SQL : identifiants séquentiels vs UUID v4', 'SITUATIONAL_QCM', 'MULTIPLE_CHOICE', 'ADVANCED',
 'Une table d''événements à 100 M lignes passe de BIGSERIAL à UUID v4 généré côté client : les écritures ralentissent.',
 'Quelles explications et alternatives ?',
 '',
 '',
 'Les inserts aléatoires (UUID v4) éclatent les pages des index B-tree (split, fragmentation, cache moins efficace) là où la séquence insère en queue (append). Alternatives : séquence (trou possibles — sans impact métier), UUIDv7 / ULID (temporellement ordonné), ou index partiel/découpage si l''aléatoire est imposé.',
 180, 20)
) AS v(title, type, selection_type, difficulty, context, question, snippet, lang, explanation, time, points)
WHERE NOT EXISTS (SELECT 1 FROM challenges c WHERE c.title = v.title);

INSERT INTO challenge_options (challenge_id, content, is_correct, display_order, explanation)
SELECT c.id, v.content, v.is_correct, v.ord, v.expl
FROM (VALUES
('SQL : ordre des colonnes d''un index composite', 'Le préfixe (client_id) absent du WHERE : l''index n''est pas parcouru efficacement', TRUE, 1, 'B-tree exploitable de gauche à droite : sans le premier prédicat, pas de navigation.'),
('SQL : ordre des colonnes d''un index composite', 'Créer un index dédié sur created_at pour les requêtes qui ne filtrent que là-dessus', TRUE, 2, 'L''indexation suit les requêtes réelles, pas la table en général.'),
('SQL : ordre des colonnes d''un index composite', 'Ajouter created_at en deuxième position de l''index existant (déjà le cas) suffit toujours', FALSE, 3, 'Inutile si le prédicat de gauche n''apparaît jamais : le suffixe ne se joint pas.'),
('SQL : ordre des colonnes d''un index composite', 'Forcer l''utilisation de l''index avec SET enable_indexscan = on', FALSE, 4, 'Les hints/paramètres ne créent pas une navigation qui n''existe pas.'),
('SQL : lignes dupliquées après un LEFT JOIN', 'La jointure 1:N duplique la ligne de gauche par enfant', TRUE, 1, 'C''est la sémantique relationnelle normale — pas une erreur de données.'),
('SQL : lignes dupliquées après un LEFT JOIN', 'Séparer agrégats (GROUP BY) et liste, ou filtrer l''enfant en sous-requête dédiée', TRUE, 2, 'Chaque grain a sa propre requête : les listes restent à une ligne par commande.'),
('SQL : lignes dupliquées après un LEFT JOIN', 'Ajouter DISTINCT pour masquer les doublons', FALSE, 3, 'Symptomatic : masque le surcoût et les colonnes mal agrégées restent fausses.'),
('SQL : lignes dupliquées après un LEFT JOIN', 'Remplacer LEFT JOIN par INNER JOIN', FALSE, 4, 'Ne résout rien : le 1:N reste, seule la perte des lignes sans enfant change.'),
('SQL : COUNT(colonne) contre COUNT(*)', 'COUNT(*) compte les lignes, COUNT(colonne) ignore les NULL', TRUE, 1, 'Règle fondamentale d''agrégation SQL.'),
('SQL : COUNT(colonne) contre COUNT(*)', 'COUNT(DISTINCT col) compte les valeurs distinctes non nulles', TRUE, 2, 'Utile pour « combien de clients différents ».'),
('SQL : COUNT(colonne) contre COUNT(*)', 'COUNT(colonne) et COUNT(*) sont strictement équivalents', FALSE, 3, 'Ils divergent dès qu''une valeur est nulle.'),
('SQL : COUNT(colonne) contre COUNT(*)', 'COUNT(NULL) renvoie le nombre de lignes nulles', FALSE, 4, 'Il renvoie 0 : NULL n''est pas compté.'),
('SQL : le filtre sur NULL ne filtre jamais', 'WHERE email = NULL renvoie jamais de ligne : il faut IS NULL', TRUE, 1, 'Comparaison avec NULL = UNKNOWN, jamais vraie.'),
('SQL : le filtre sur NULL ne filtre jamais', 'NULL signifie « colonne vide » et est égal à lui-même', FALSE, 2, 'Inconnu ≠ inconnu : la logique à trois valeurs s''applique.'),
('SQL : le filtre sur NULL ne filtre jamais', 'WHERE COALESCE(email, "") = "" produit le même résultat en pratique', TRUE, 3, 'Alternative valide — à condition de comprendre la conversion implicite de NULL en vide.'),
('SQL : le filtre sur NULL ne filtre jamais', 'Le NULL est stocké comme chaîne vide en PostgreSQL', FALSE, 4, 'Absurde : NULL est un marqueur d''absence, pas une valeur.'),
('SQL : ORDER BY absent sur une pagination', 'Sans ORDER BY, l''ordre n''est garanti à aucune étape du traitement', TRUE, 1, 'Le plan (parallélisme, pages) peut changer d''une exécution à l''autre.'),
('SQL : ORDER BY absent sur une pagination', 'Pagination stable : ORDER BY sur une clé totale, tie-break inclus', TRUE, 2, 'L''id en dernier évite les doublons/oublis entre pages.'),
('SQL : ORDER BY absent sur une pagination', 'LIMIT/OFFSET inclut implicitement un tri sur la clé primaire', FALSE, 3, 'Aucune garantie du genre dans le standard ni dans PG.'),
('SQL : ORDER BY absent sur une pagination', 'Le désordre vient toujours du côté applicatif (affichage)', FALSE, 4, 'Le serveur lui-même peut renvoyer l''ordre qu''il veut.'),
('SQL : montants en DOUBLE PRECISION', 'Les flottants binaires ne représentent pas exactement les décimales', TRUE, 1, 'Somme de valeurs inexactes = dérive comptable.'),
('SQL : montants en DOUBLE PRECISION', 'NUMERIC(p,s) : arithmétique décimale exacte à précision déclarée', TRUE, 2, 'Le type monétaire standard (ou MONEY selon les conventions).'),
('SQL : montants en DOUBLE PRECISION', 'DOUBLE PRECISION est parfait tant qu''on arrondit à l''affichage', FALSE, 3, 'Les pertes intermédiaires de précision faussent les agrégats.'),
('SQL : montants en DOUBLE PRECISION', 'Il faut INTEGER en centimes pour être exact', FALSE, 4, 'Technique possible mais fragile (débordement, virgules variables) — NUMERIC existe pour cela.'),
('SQL : clé étrangère sans index', 'Chaque écriture parente scanne la table enfant pour vérifier l''absence d''orphelin', TRUE, 1, 'Le mécanisme de vérification de FK sans index = SCAN par écriture.'),
('SQL : clé étrangère sans index', 'Indexer systématiquement les colonnes de clés étrangères', TRUE, 2, 'Règle de conception à imposer en revue de schéma.'),
('SQL : clé étrangère sans index', 'La clé primaire de la table parente suffit toujours', FALSE, 3, 'Elle indexe la table parente, pas la colonne FK côté enfant.'),
('SQL : clé étrangère sans index', 'Ajouter ON DELETE CASCADE règle le problème de performance', FALSE, 4, 'Change la sémantique de suppression sans rien au coût de vérification.'),
('SQL : le planificateur choisit un seq scan', 'EXPLAIN (ANALYZE, BUFFERS) d''abord : le plan est une décision, pas un bug', TRUE, 1, 'Comprendre avant d''agir : sélectivité, coûts estimés, buffers réels.'),
('SQL : le planificateur choisit un seq scan', 'Une faible sélectivité peut rendre le seq scan le meilleur choix', TRUE, 2, 'Si 40 % des lignes matchent, parcourir la table est souvent moins cher.'),
('SQL : le planificateur choisit un seq scan', 'Statistiques à jour (ANALYZE) et filtres sargables conditionnent la décision', TRUE, 3, 'Mauvaises estimations = mauvais plan.'),
('SQL : le planificateur choisit un seq scan', 'Forcer indexscan=true partout est la bonne pratique', FALSE, 4, 'Interdire au planner de choisir le meilleur plan = régressions garanties.'),
('SQL : niveaux d''isolation et lecture fantôme', 'Sous READ COMMITTED, chaque voit l''état le plus récent : fantômes possibles', TRUE, 1, 'La lecture d''un ensemble ne verrouille pas les lignes futures du jeu.'),
('SQL : niveaux d''isolation et lecture fantôme', 'REPEATABLE READ fige le jeu de données pour la transaction', TRUE, 2, 'Adapté aux traitements batch qui doivent raisonner sur une image cohérente.'),
('SQL : niveaux d''isolation et lecture fantôme', 'Toute divergence vient forcément d''un bug applicatif', FALSE, 3, 'Le phantom est un comportement standard de l''isolation faible.'),
('SQL : niveaux d''isolation et lecture fantôme', 'SERIALIZABLE ne peut échouer sous aucune circonstance', FALSE, 4, 'Il échoue précisément en conflit — il faut le traiter (retry).'),
('SQL : deadlock entre deux transactions', 'Aligner l''ordre d''acquisition des verrous sur toutes les requêtes', TRUE, 1, 'Sans cycle circulaire, pas de deadlock possible.'),
('SQL : deadlock entre deux transactions', 'Borner la durée des transactions (verrous libérés vite)', TRUE, 2, 'Plus la transaction vit, plus elle accumule et retient des verrous.'),
('SQL : deadlock entre deux transactions', 'Augmenter le nombre de verrous disponibles (setting)', FALSE, 3, 'Aucun tel réglage : les verrous sont gagnés par ligne/table.'),
('SQL : deadlock entre deux transactions', 'Sérialiser tout le service avec un seul gros SELECT FOR UPDATE', FALSE, 4, 'Élimine la concurrence — guérir le patient en l''endormant.'),
('SQL : mise à jour globale sans ciblage', 'Verrouillage ligne à ligne + WAL massif = opération longue et bloquante', TRUE, 1, 'Millions de lignes = verrous maintenus, bloat, réplication ralentie.'),
('SQL : mise à jour globale sans ciblage', 'Traiter par lots bornés (id/plage) avec pause entre les lots', TRUE, 2, 'Charge étalée, verrous brefs, interruption possible.'),
('SQL : mise à jour globale sans ciblage', 'Passer en TRUNCATE + réimportation pour aller plus vite', FALSE, 3, 'Détructurant : perd les lignes hors périmètre et casse les FK.'),
('SQL : mise à jour globale sans ciblage', 'La transaction globale est automatiquement mise en lecture seule', FALSE, 4, 'Invention : PG n''impose rien de tel sur UPDATE.'),
('SQL : compteur concurrent et mise à jour perdue', 'SELECT ... FOR UPDATE à la lecture : la ligne reste verrouillée jusqu''à commit', TRUE, 1, 'Interdit l''entrée d''une deuxième transaction entre lecture et écriture.'),
('SQL : compteur concurrent et mise à jour perdue', 'UPDATE ... SET nb = nb + 1 : incrémentation atomique sans relecture', TRUE, 2, 'L''opération se joue sous le verrou de ligne, une seule fois.'),
('SQL : compteur concurrent et mise à jour perdue', 'Augmenter le niveau d''isolation par défaut de la base entière', FALSE, 3, 'Surcoût global pour un motif localisé — cibler la requête.'),
('SQL : compteur concurrent et mise à jour perdue', 'Ajouter un sleep aléatoire avant l''écriture', FALSE, 4, 'Réduit la probabilité sans jamais l''éliminer — non déterministe.'),
('SQL : OFFSET profond sur une table chargée', 'OFFSET force à compter et jeter les lignes : coût croissant avec la profondeur', TRUE, 1, 'Page 40 000 = 40 000 lignes parcourues pour rien.'),
('SQL : OFFSET profond sur une table chargée', 'Keyset : WHERE (colonne, id) < (dernière_valeure, dernier_id) + LIMIT', TRUE, 2, 'Accès direct au segment suivant : coût constant.'),
('SQL : OFFSET profond sur une table chargée', 'Augmenter le cache partagé règle le temps des pages profondes', FALSE, 3, 'Améliore l''I/O, pas le travail de tri/comptage inutile.'),
('SQL : OFFSET profond sur une table chargée', 'OFFSET reste performant si l''index couvre ORDER BY', FALSE, 4, 'L''index accélère le tri, pas le saut des lignes précédentes.'),
('SQL : Bornes de date et BETWEEN', 'BETWEEN est inclusif : les fractions après 23:59:59 échappent à la borne', TRUE, 1, 'Bug silencieux de couverture : lignes manquantes à minuit.'),
('SQL : Bornes de date et BETWEEN', 'Bornes semi-ouvertes : >= début AND < lendemain — robuste et indexable', TRUE, 2, 'La forme canonique des fenêtres temporelles.'),
('SQL : Bornes de date et BETWEEN', 'Ajouter ".999999" à la borne haute règle définitivement le problème', FALSE, 3, 'Colle fragile : repose sur la précision stockée (microsecondes).'),
('SQL : Bornes de date et BETWEEN', 'BETWEEN fonctionne correctement sur les DATE (sans heure)', TRUE, 4, 'Vrai : le piège ne vaut que pour les timestamps — précision utile.'),
('SQL : expression sur colonne = index ignoré', 'Une fonction sur la colonne rend la recherche non sargable', TRUE, 1, 'L''index est sur email brut, pas sur LOWER(email).'),
('SQL : expression sur colonne = index ignoré', 'Index sur l''expression : CREATE INDEX ON t (LOWER(email))', TRUE, 2, 'PostgreSQL supporte nativement les index d''expression.'),
('SQL : expression sur colonne = index ignoré', 'Colonne générée stockée (GENERATED ALWAYS AS ... ) puis index', TRUE, 3, 'Alternative : matérialise la valeur au moment de l''écriture.'),
('SQL : expression sur colonne = index ignoré', 'Inverser les côtés de l''égalité suffit toujours à activer l''index', FALSE, 4, 'Le planner commute les opérandes : la fonction reste le blocage.'),
('SQL : motif LIKE et types d''index', 'Préfixe ("text%") exploitable en B-tree ; occurrence centrale : scan', TRUE, 1, 'L''ordre lexicographique du B-tree sert les préfixes.'),
('SQL : motif LIKE et types d''index', 'Index de trigrammes (pg_trgm) pour les motifs contenant % des deux côtés', TRUE, 2, 'Reconnaît les sous-chaînes quel que soit le positionnement.'),
('SQL : motif LIKE et types d''index', 'ILIKE ajoute automatiquement un index adapté', FALSE, 3, 'ILIKE gère la casse, pas l''indexation — pg_trgm reste nécessaire.'),
('SQL : motif LIKE et types d''index', 'Remplacer LIKE par une regex active les index B-tree', FALSE, 4, 'Aucun lien : les regex ne sont pas sargables non plus.'),
('SQL : UNION contre UNION ALL', 'UNION impose une étape de déduplication (tri/hash) coûteuse', TRUE, 1, 'Sur 1,3 M lignes, cette étape domine le temps total.'),
('SQL : UNION contre UNION ALL', 'UNION ALL concatène sans contrôle : réservé aux jeux disjoints garantis', TRUE, 2, 'Décision de justesse : exactitude vs coût.'),
('SQL : UNION contre UNION ALL', 'UNION ALL est toujours préférable car plus rapide', FALSE, 3, 'Seulement si les doublons sont impossibles — sinon résultats faux.'),
('SQL : UNION contre UNION ALL', 'Le DISTINCT final de UNION se remplace par un GROUP BY plus rapide', FALSE, 4, 'Même travail de déduplication, autre nom.'),
('SQL : cast implicite dans une jointure', 'La conversion appliquée à la colonne empêche l''exploitation de l''index', TRUE, 1, 'Index sur BIGINT inutilisable si la colonne est castée en texte.'),
('SQL : cast implicite dans une jointure', 'Risques de erreurs de conversion et de valeurs sans équivalent', TRUE, 2, '"12x" ou vides : correspondances faussées au passage.'),
('SQL : cast implicite dans une jointure', 'Corriger le type à la source (alignement des colonnes) plutôt qu''à la volée', TRUE, 3, 'Le cast dans la requête masque un défaut de modèle.'),
('SQL : cast implicite dans une jointure', 'Ajouter COLLATE FOR CASE insensitive résout le problème d''index', FALSE, 4, 'Le souci est un type, pas une collation.'),
('SQL : sous-requête corrélée exécutée par ligne', 'Anti-join en NOT EXISTS / LEFT JOIN ... IS NULL : un seul passage par table', TRUE, 1, 'Le planner reconnaît et planifie correctement l''anti-join.'),
('SQL : sous-requête corrélée exécutée par ligne', 'IN avec un jeu contenant NULL renvoie jamais TRUE — piège de résultat', TRUE, 2, 'D''où la préférence systématique pour NOT EXISTS.'),
('SQL : sous-requête corrélée exécutée par ligne', 'Materialiser le jeu en CTE (WITH) si réutilisé et non volatile', TRUE, 3, 'Pertinent selon PG version et usage — décision à mesurer.'),
('SQL : sous-requête corrélée exécutée par ligne', 'Ajouter LIMIT pour réduire le coût de la sous-requête', FALSE, 4, 'Changer le résultat n''est pas optimiser — confusion classique.'),
('SQL : plan dégradé après montée de volumétrie', 'Statistiques / sélectivité réelle : ANALYZE puis comparaison de plans', TRUE, 1, 'Sans stats à jour, le planner calcule sur un modèle faux.'),
('SQL : upsert et course entre deux écritures', 'INSERT ... ON CONFLICT ... DO UPDATE : décision atomique au plus près des données', TRUE, 1, 'La fenêtre de course disparaît : PostgreSQL arbitre sous verrou.'),
('SQL : upsert et course entre deux écritures', 'La clé d''unicité (PK/unique) porte la protection, pas le code applicatif', TRUE, 2, 'Deux processus ne peuvent décider qu''une seule fois de la même clé.'),
('SQL : upsert et course entre deux écritures', 'SELECT puis INSERT dans la même transaction suffit', FALSE, 3, 'Sous READ COMMITTED, la fenêtre entre les deux instructions reste ouverte.'),
('SQL : upsert et course entre deux écritures', 'Ajouter un sleep aléatoire au second importeur', FALSE, 4, 'Heuristique non déterministe : la course reste possible.'),
('SQL : plan dégradé après montée de volumétrie', 'EXPLAIN (ANALYZE, BUFFERS) pour confirmer l''estimation contre le réel', TRUE, 2, 'Les lignes réelles vs estimées révèlent le décalage.'),
('SQL : plan dégradé après montée de volumétrie', 'Distributions skewées (valeurs rares) : statistiques étendues ou stats par colonne', TRUE, 3, 'Une valeur à 0,01 % mal estimée détruit le plan de filtrage.'),
('SQL : plan dégradé après montée de volumétrie', 'Forcer l''ancien plan avec un hint dès la régression', FALSE, 4, 'Colle technique : le plan faux redeviendra faux à la prochaine variation.'),
('SQL : autovacuum ne suit plus la charge', 'Seuils d''autovacuum inadaptés au taux d''écriture : dead tuples qui s''accumulent', TRUE, 1, 'Bloat : scans plus longs, index plus hauts, espace perdu.'),
('SQL : autovacuum ne suit plus la charge', 'Transactions longues qui bloquent le vacuum (horizon xmin)', TRUE, 2, 'Une session oubliée peut empêcher tout nettoyage pendant des heures.'),
('SQL : autovacuum ne suit plus la charge', 'Régler scale_factor/threshold par table surdimensionnée', TRUE, 3, 'Les tables énormes ont des seuils par défaut trop tardifs.'),
('SQL : autovacuum ne suit plus la charge', 'VACUUM (FULL) + REINDEX en fenêtre de maintenance si le bloat est installé', TRUE, 4, 'Réorganise physiquement — verrouillant, donc planifié.'),
('SQL : index BRIN sur une table temporelle', 'BRIN : quelques Mo pour des Tb, parfait sur données append-only triées', TRUE, 1, 'Résumé par bloc plutôt que clé par clé.'),
('SQL : index BRIN sur une table temporelle', 'La pertinence dépend de la corrélation physique / valeur (ordre d''insertion)', TRUE, 2, 'Données ingérées hors ordre = BRIN inefficace.'),
('SQL : index BRIN sur une table temporelle', 'B-tree reste inégalé pour les recherches ponctuelles exactes', TRUE, 3, 'Le choix est un arbitrage d''usage, pas un dogme.'),
('SQL : index BRIN sur une table temporelle', 'BRIN et B-tree ont exactement le même coût d''écriture', FALSE, 4, 'BRIN est quasi nul en écriture — l''inverse en fait.'),
('SQL : partitionnement de table volume géant', 'Partition pruning : le planner ne touche que les partitions pertinentes', TRUE, 1, 'Filtrage sur la clé de partition = I/O limitée au nécessaire.'),
('SQL : partitionnement de table volume géant', 'DROP/ATTACH de partition quasi instantané contre DELETE massif', TRUE, 2, 'Le vrai gain opérationnel de la purge périodique.'),
('SQL : partitionnement de table volume géant', 'Maintenance localisée (REINDEX par partition possible)', TRUE, 3, 'Opérations plus courtes et moins bloquantes.'),
('SQL : partitionnement de table volume géant', 'Aucune complexité ajoutée : le partitionnement est transparent partout', FALSE, 4, 'Clés, séquences, contraintes, requêtes cross-partitions : vraie complexité.'),
('SQL : anomalies de sérialisation sous forte charge', 'L''échec est normal : signal d''un conflit détecté, pas une panne', TRUE, 1, 'L''isolation forte paie son prix en conflits.'),
('SQL : anomalies de sérialisation sous forte charge', 'Retry borné avec backoff — jamais de boucle infinie', TRUE, 2, 'La bonne réponse applicative à une anomalie transitoire.'),
('SQL : anomalies de sérialisation sous forte charge', 'Transactions courtes pour réduire la fenêtre de conflit', TRUE, 3, 'Prévention à la source du phénomène.'),
('SQL : anomalies de sérialisation sous forte charge', 'Reculer en READ COMMITTED « pour éviter les erreurs »', FALSE, 4, 'Supprime la garantie d''intégrité plutôt que de gérer les conflits.'),
('SQL : identifiants séquentiels vs UUID v4', 'Inserts aléatoires : fragmentation des pages d''index (splits, cache moins efficace)', TRUE, 1, 'Le B-tree append en queue aime l''ordre ; le v4 l''éclate.'),
('SQL : identifiants séquentiels vs UUID v4', 'UUIDv7/ULID : aléatoire mais temporellement ordonné', TRUE, 2, 'Compromis moderne : distribuable ET inséré en queue.'),
('SQL : identifiants séquentiels vs UUID v4', 'La séquence peut créer des trous (rollback) : sans impact métier en général', TRUE, 3, 'Souvent un faux problème — vérifier l''exigence réelle de continuité.'),
('SQL : identifiants séquentiels vs UUID v4', 'Générer le côté base résout toujours le problème de duplication', FALSE, 4, 'Ne concerne pas la fragmentation — c''est un autre débat (conflit d''écriture).')
) AS v(title, content, is_correct, ord, expl)
JOIN challenges c ON c.title = v.title
WHERE NOT EXISTS (SELECT 1 FROM challenge_options o WHERE o.challenge_id = c.id AND o.display_order = v.ord);

-- ---------------------------------------------------------------------
-- 4 PROBLEM_SOLVING
-- ---------------------------------------------------------------------
INSERT INTO challenges (title, type, selection_type, difficulty, context, question, code_snippet, code_language, explanation, estimated_time_seconds, active, points, created_at, updated_at)
SELECT v.title, v.type, v.selection_type, v.difficulty, v.context, v.question,
       NULLIF(v.snippet, ''), NULLIF(v.lang, ''), v.explanation, v.time, TRUE, v.points,
       CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM (VALUES
('SQL : requête de 30 s sur 50 millions de lignes', 'PROBLEM_SOLVING', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Le rapport mensuel de l''équipe prend 30 secondes et son temps double chaque trimestre avec la croissance.',
 'Décris ta démarche complète d''optimisation, de la mesure à la mise en production.',
 '',
 '',
 '1) Capturer la charge réelle et EXPLAIN (ANALYZE, BUFFERS) sur cette requête. 2) Identifier le goulot (scan complet ? tri ? agrégat ? jointure explosée ?). 3) Choisir l''action ciblée : index composite aligné sur filtre+tri, réécriture (anti-join, agrégat anticipé), ou découpage. 4) Mesurer avant/après sur jeu représentatif. 5) Déployer sans downtime (index CONCURRENTLY) et surveiller. Toute étape sans mesure est une hypothèse.',
 240, 25),
('SQL : COUNT(*) du dashboard qui s''effondre', 'PROBLEM_SOLVING', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Le tableau de bord compte 14 indicateurs en COUNT/SUM sur des tables de plusieurs dizaines de millions de lignes : 6 s à chaque ouverture.',
 'Quelles stratégies combinationnes-tu et dans quel ordre ?',
 '',
 '',
 '1) Bornage : ne compter que ce qui s''affiche réellement. 2) Pré-agrégation : table de faits/matérialisée rafraîchie (refresh incrémental) ou agrégats dénormalisés tenus à l''écriture. 3) Cache applicatif avec TTL court si la fraîcheur le permet. 4) Index couvrants pour les requêtes conservées. 5) Mesure : laisser le COUNT exact aux écrans d''administration à faible trafic.',
 180, 15),
('SQL : changer le type d''une colonne en production', 'PROBLEM_SOLVING', 'SINGLE_CHOICE', 'ADVANCED',
 'La colonne users.ref (VARCHAR) doit devenir BIGINT : 40 M lignes, écritures continues 24/7.',
 'Quelle procédure sans interruption ni blocage long ?',
 '',
 '',
 'Préparer (type cible, valeurs non convertibles = plan de nettoyage) → échelonner la réécriture par lots (UPDATE par tranche d''id avec WHERE USING) pour alimuler la table en accès partagé → créer la contrainte d''abord en NOT VALID puis VALIDATE (bref verrou) → deux-trois ALTER courts (PG permet d''ajouter contrainte + switch en phase). Optionnel : colonne temporelle swap-able + bascule applicative (expand/contract) pour un zero-downtime total.',
 240, 25),
('SQL : décisions de schéma pour RGPD', 'PROBLEM_SOLVING', 'SINGLE_CHOICE', 'ADVANCED',
 'Un utilisateur exerce son droit à l''effacement : données personnelles présentes dans users, orders, logs, exports, sauvegardes.',
 'Quelle stratégie d''effacement mets-tu en place ?',
 '',
 '',
 'Cartographier les flux (tables, logs applicatifs, exports, sauvegardes chiffrées avec rétention) → choisir la forme d''effacement par flux (DELETE réel vs anonymisation irréversible conservant les agrégats métier : « user supprimé » + données devenant non personnelles) → exécuter par lots avec traçabilité → purge des logs et exports → VACUUM pour libérer l''espace → preuve d''exécution. Les sauvegardes suivent une rétention documentée.',
 240, 25)
) AS v(title, type, selection_type, difficulty, context, question, snippet, lang, explanation, time, points)
WHERE NOT EXISTS (SELECT 1 FROM challenges c WHERE c.title = v.title);

-- ---------------------------------------------------------------------
-- 5 CODE_REVIEW
-- ---------------------------------------------------------------------
INSERT INTO challenges (title, type, selection_type, difficulty, context, question, code_snippet, code_language, explanation, estimated_time_seconds, active, points, created_at, updated_at)
SELECT v.title, v.type, v.selection_type, v.difficulty, v.context, v.question,
       v.snippet, v.lang, v.explanation, v.time, TRUE, v.points,
       CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM (VALUES
('SQL Review : jointure sans condition de filtre', 'CODE_REVIEW', 'MULTIPLE_CHOICE', 'INTERMEDIATE',
 'Une vue de reporting agrège les ventes et les retours clients.',
 'Quels problèmes identifiez-vous dans ce code ?',
 'SELECT c.name,
       SUM(v.amount) AS total
FROM   customers c
JOIN   sales    v ON v.customer_id = c.id
JOIN   returns  r ON r.customer_id = c.id
GROUP  BY c.name;',
 'sql',
 'L''absence de filtre/condition entre sales et returns crée une multiplication croisée (chaque vente × chaque retour du client) : les totaux sont faux, silencieusement. Et sans WHERE période, la vue scanne l''historique complet. Filtrer la période et exprimer les deux agrégats séparément (jointures dédiées avec dates, ou sous-requêtes agrégées).',
 180, 20),
('SQL Review : UPDATE sans garde-fou', 'CODE_REVIEW', 'MULTIPLE_CHOICE', 'JUNIOR',
 'Un correctif de statut est exécuté à la main par l''équipe.',
 'Quels problèmes identifiez-vous dans ce code ?',
 'UPDATE subscriptions
SET status = ''canceled'';
-- et dans un autre script :
DELETE FROM session_tokens WHERE created_at < NOW();',
 'sql',
 'Le premier UPDATE sans WHERE modifie TOUTES les lignes (d''autres en souffrent). Le DELETE est large mais borné — acceptable, à défaut d''être transactionnelt (BEGIN/ROLLBACK test) et journalisé. Règle : toute écriture destructive commence par un SELECT équivalent dans la même transaction.',
 120, 15),
('SQL Review : pagination pendant écritures concurrentes', 'CODE_REVIEW', 'MULTIPLE_CHOICE', 'INTERMEDIATE',
 'Un export « page par page » pendant que des commandes sont créées en continu.',
 'Quels problèmes identifiez-vous dans ce code ?',
 'SELECT * FROM orders
ORDER BY created_at DESC
LIMIT 100 OFFSET 1200;',
 'sql',
 'Pendant l''export, les insertions décalent les positions : OFFSET saute des lignes déjà vues ou en répète. La pagination par offset est unstable sous écriture — utiliser le keyset (WHERE (created_at, id) < dernier_courant) qui ancre chaque page sur des valeurs, pas sur un rang.',
 180, 20),
('SQL Review : boucle applicative au lieu d''une agrégation', 'CODE_REVIEW', 'MULTIPLE_CHOICE', 'INTERMEDIATE',
 'Un rapport de ventes par région est généré par le back-end.',
 'Quels problèmes identifiez-vous dans ce code ?',
 'List<Region> regions = repo.findAll();
for (Region r : regions) {
    long n = jdbcTemplate.queryForObject(
        "SELECT count(*) FROM sales WHERE region_id = " + r.getId(),
        Long.class);
    r.setSales(n);
}',
 'sql',
 'Deux défauts majeurs : N requêtes (1 + nb régions) alors qu''une seule agrégation GROUP BY suffirait (réseau, aller-retours, verrous), et la concaténation de r.getId() dans la requête — une valeur techniquement sûre ici devient réflexe dangereux (paramétrage systématique). Réécrire en GROUP BY region_id + mappe applicative.',
 180, 20),
('SQL Review : opération destructrice sans filet', 'CODE_REVIEW', 'MULTIPLE_CHOICE', 'ADVANCED',
 'Script de purge de données de test en staging... exécuté sur le mauvais environnement (mêmes scripts, mauvais profil shell).',
 'Quels problèmes identifiez-vous dans ce code ?',
 'TRUNCATE TABLE audit_log CASCADE;

-- même script sur prod :
TRUNCATE TABLE events, users;',
 'sql',
 'TRUNCATE : rapide mais DÉTRUCTIF (pas de WHERE, CASCADE efface les FK liées — ici l''audit !) et il casse les FK pointant vers les tables. Pas de garde ni de transaction confirmée. Corriger : environnement contrôlé (motif du profil), transaction explicite avec SELECT préalable + rollback de vérification, DELETE borné ou ATTACH/DROP de partitions, et validation humaine pour le destructif.',
 240, 25)
) AS v(title, type, selection_type, difficulty, context, question, snippet, lang, explanation, time, points)
WHERE NOT EXISTS (SELECT 1 FROM challenges c WHERE c.title = v.title);
INSERT INTO challenge_options (challenge_id, content, is_correct, display_order, explanation, severity)
SELECT c.id, v.content, v.is_correct, v.ord, v.expl, v.sev
FROM (VALUES
          ('SQL Review : jointure sans condition de filtre', 'Croisement sales × returns : chaque montant est multiplié par le nombre de retours', TRUE, 1, 'Résultats faux silencieusement — le pire type d''erreur de reporting.', 'DATABASE'),
          ('SQL Review : jointure sans condition de filtre', 'Aucune borne de période : scan de l''historique complet', TRUE, 2, 'Performance + logique : le rapport doit délimiter son périmètre.', 'PERFORMANCE'),
          ('SQL Review : jointure sans condition de filtre', 'Exprimer les deux agrégats séparément (sous-requêtes/jointures de périodes dédiées)', TRUE, 3, 'Chaque mesure garde sa propre granularité.', 'ARCHITECTURE'),
          ('SQL Review : jointure sans condition de filtre', 'GROUP BY c.name suffit à garantir la justesse des totaux', FALSE, 4, 'L''agrégat agrège les lignes croisées — il agrège l''erreur.', NULL),
          ('SQL Review : UPDATE sans garde-fou', 'UPDATE sans WHERE : toutes les lignes basculent', TRUE, 1, 'À fortiori en environnement partagé / si le script dérive en prod.', 'BUG'),
          ('SQL Review : UPDATE sans garde-fou', 'Transaction + SELECT préalable dans la même transaction (aperçu + rollback possible)', TRUE, 2, '« Voir avant d''écrire » : réflexe de sécurité fondamental.', 'CODE_QUALITY'),
          ('SQL Review : UPDATE sans garde-fou', 'DELETE borné : acceptable s''il est transactionnel et journalisé', TRUE, 3, 'Le périmètre est explicite — reste à valider avant COMMIT.', 'CODE_QUALITY'),
          ('SQL Review : UPDATE sans garde-fou', 'La base refuse automatiquement les écritures sans WHERE', FALSE, 4, 'Aucune telle protection — PostgreSQL obéit.', NULL),
          ('SQL Review : pagination pendant écritures concurrentes', 'OFFSET instable pendant écritures : lignes sautées ou dupliquées', TRUE, 1, 'Le rang change entre chaque page : la pagination perd sa référence.', 'BUG'),
          ('SQL Review : pagination pendant écritures concurrentes', 'Keyset : ancrer chaque page sur les valeurs de la dernière ligne vue', TRUE, 2, 'Stable quelles que soient les insertions concurrentes.', 'DATABASE'),
          ('SQL Review : pagination pendant écritures concurrentes', 'L''export doit figer son périmètre (snapshot) s''il doit être exhaustif', TRUE, 3, 'Alternative : WHERE created_at < début d''export — périmètre immuable.', 'ARCHITECTURE'),
          ('SQL Review : pagination pendant écritures concurrentes', 'ORDER BY sur index rend la pagination stable sous écriture', FALSE, 4, 'Le tri est stable, les POSITIONS ne le sont pas.', NULL),
          ('SQL Review : boucle applicative au lieu d''une agrégation', 'N requêtes (1 par région) : coût réseau/aller-retours évitable', TRUE, 1, 'Une GROUP BY fait le travail côté base en un passage.', 'PERFORMANCE'),
          ('SQL Review : boucle applicative au lieu d''une agrégation', 'Concaténation de valeur dans la requête : mauvais réflexe même si safe ici', TRUE, 2, 'Paramétrage systématique pour que le pattern reste sûr partout.', 'SECURITY'),
          ('SQL Review : boucle applicative au lieu d''une agrégation', 'Remplacer par SELECT region_id, COUNT(*) ... GROUP BY region_id + mappe', TRUE, 3, 'Une requête, un aller-retour, agrégation à l''endroit optimal.', 'ARCHITECTURE'),
          ('SQL Review : boucle applicative au lieu d''une agrégation', 'Préférer findAll() qui est toujours plus rapide que les requêtes dédiées', FALSE, 4, 'findAll charge tout en mémoire — l''inverse d''une agrégation ciblée.', NULL),
          ('SQL Review : opération destructrice sans filet', 'TRUNCATE : ni WHERE, ni annulation simple, CASCADE efface les liens FK', TRUE, 1, 'Outil de structure, pas de purge conditionnelle.', 'BUG'),
          ('SQL Review : opération destructrice sans filet', 'Absence de garde environnement : même script sur prod = catastrophe', TRUE, 2, 'La sécurité doit tenir dans le script, pas dans la mémoire de l''opérateur.', 'SECURITY'),
          ('SQL Review : opération destructrice sans filet', 'Préférer DELETE borné / détachement de partition (réversible, auditable)', TRUE, 3, 'Le destructif se planifie ; le réversible se lance.', 'CODE_QUALITY'),
          ('SQL Review : opération destructrice sans filet', 'TRUNCATE est rapide : à utiliser dès que la table doit être vidée', FALSE, 4, 'Vitesse sans sémantique = risque — le cœur du problème.', NULL)
     ) AS v(title, content, is_correct, ord, expl, sev)
         JOIN challenges c ON c.title = v.title
WHERE NOT EXISTS (SELECT 1 FROM challenge_options o WHERE o.challenge_id = c.id AND o.display_order = v.ord);

-- ---------------------------------------------------------------------
-- 5 SEQUENTIAL_REASONING
-- ---------------------------------------------------------------------
INSERT INTO challenges (title, type, selection_type, difficulty, context, question, code_snippet, code_language, explanation, estimated_time_seconds, active, points, created_at, updated_at)
SELECT v.title, v.type, v.selection_type, v.difficulty, v.context, v.question,
       NULLIF(v.snippet, ''), NULLIF(v.lang, ''), v.explanation, v.time, TRUE, v.points,
       CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM (VALUES
('SQL : requête devenue lente — démarche', 'SEQUENTIAL_REASONING', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Une requête métier était à 80 ms, elle passe à 2,5 s depuis la dernière montée de données.',
 'Remets dans l''ordre les étapes d''investigation et de correction.',
 '',
 '',
 'Mesurer le plan réel avant toute hypothèse, comprendre l''écart estimé/réel, agir sur la cause (stats, index, réécriture), mesurer à nouveau, puis institutionaliser la surveillance. Corriger sans EXPLAIN revient à deviner.',
 180, 15),
('SQL : ajouter un index sur base chargée', 'SEQUENTIAL_REASONING', 'SINGLE_CHOICE', 'ADVANCED',
 'Table de 120 M lignes, index manquant sur une colonne filtrée par une requête critique. Écritures continues.',
 'Quel est l''ordre sûr de mise en œuvre ?',
 '',
 '',
 'Valider le besoin (plan + sélectivité réelle) → CREATE INDEX CONCURRENTLY (pas de verrou bloquant, tolère les erreurs à surveiller) → vérifier qu''il est utilisé (EXPLAIN) et qu''il est sain (invalid/tués à contrôler) → nettoyer l''ancien si doublon → surveiller bloat/écritures. Un CREATE INDEX simple bloquerait les écritures pendant des minutes.',
 180, 20),
('SQL : import massif sans casser le service', 'SEQUENTIAL_REASONING', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'Import de 10 M lignes dans une table en production, pendant les heures ouvrées.',
 'Quel ordre de traitement recommandes-tu ?',
 '',
 '',
 'Préparer hors ligne (staging, COPY rapide, contraintes en NO VALIDATE/DEFERRIBLE) → valider le jeu (rejets, doublons, contrôles métier) → intégrer par lots/échanges courts (INSERT ... SELECT depuis staging, ou ATTACH) → vérifier contraintes et index → VACUUM/ANALYZE si nécessaire. Importer ligne à ligne en INSERT individuel pendant les heures de service est la méthode à éviter.',
 180, 15),
('SQL : doublons bloquant une contrainte UNIQUE', 'SEQUENTIAL_REASONING', 'SINGLE_CHOICE', 'INTERMEDIATE',
 'L''équipe veut ajouter UNIQUE (email, org_id) sur une table de 5 M lignes : l''ALTER échoue, il y a des doublons.',
 'Quel est l''ordre correct de résolution ?',
 '',
 '',
 'Identifier les doublons (requête de détection) → arbitrer le sort de chacun (fusionner, conserver le plus récent, corriger la donnée source — décision MÉTIER, pas technique) → appliquer par lots avec traçabilité → créer l''ALTER en CONCURRENTLY si indispo continue → ajouter la surveillance applicative pour empêcher les nouveaux doublons. Créer la contrainte avant d''avoir arbitré revient à faire échouer le déploiement sans avancer.',
 240, 25),
('SQL : purge de colonnes personnelles', 'SEQUENTIAL_REASONING', 'SINGLE_CHOICE', 'ADVANCED',
 'Suppression d''une donnée personnelle (champ téléphone) présente dans une table principale, des tables de logs applicatifs et les exports.',
 'Quelles étapes dans quel ordre ?',
 '',
 '',
 'Cartographier toutes les présences (base, logs, exports, sauvegardes) → stopper les réplications/exports qui recopient la donnée → effacer la donnée à la source (lots + audit) → nettoyer les dérivés (logs, exports, caches) → VACUUM pour libérer l''espace physique → documenter la rétention des sauvegardes restantes. Effacer dans la table principale seul laisse la donnée vivre ailleurs.',
 240, 25)
) AS v(title, type, selection_type, difficulty, context, question, snippet, lang, explanation, time, points)
WHERE NOT EXISTS (SELECT 1 FROM challenges c WHERE c.title = v.title);

INSERT INTO challenge_options (challenge_id, content, is_correct, display_order, explanation)
SELECT c.id, v.content, v.is_correct, v.ord, v.expl
FROM (VALUES
('SQL : requête devenue lente — démarche', 'EXPLAIN (ANALYZE, BUFFERS) sur la requête réelle en conditions réelles', TRUE, 1, 'Le plan et les écarts estimé/réel sont la seule base factuelle.'),
('SQL : requête devenue lente — démarche', 'Diagnostiquer l''écart (stats obsolètes ? sélectivité ? séquentiel inattendu ?)', TRUE, 2, 'Comprendre POURQUOI avant de choisir la correction.'),
('SQL : requête devenue lente — démarche', 'Corriger ciblé : ANALYZE/statistiques, index aligné, ou réécriture', TRUE, 3, 'L''action découle du diagnostic, jamais l''inverse.'),
('SQL : requête devenue lente — démarche', 'Mesurer avant/après sur le même jeu de charge', TRUE, 4, 'La preuve du gain — sinon optimisation non vérifiée.'),
('SQL : requête devenue lente — démarche', 'Ajouter un index sur chaque colonne du WHERE « au cas où »', FALSE, 5, 'Index morts = écritures ralenties, espace, autovacuum en plus.'),
('SQL : requête devenue lente — démarche', 'Réécrire entièrement la requête avant de la profiler', FALSE, 6, 'Réécriture aveugle : coût élevé, gain inconnu.'),
('SQL : ajouter un index sur base chargée', 'Valider le besoin par le plan et la sélectivité réelle', TRUE, 1, 'Un index non prouvé = dette immédiate.'),
('SQL : ajouter un index sur base chargée', 'CREATE INDEX CONCURRENTLY pour éviter le verrou bloquant', TRUE, 2, 'L''équivalent sans downtime sur base en production.'),
('SQL : ajouter un index sur base chargée', 'Vérifier l''état de l''index (invalid/tués) et son utilisation', TRUE, 3, 'Un CONCURRENTLY interrompu laisse un index inutilisable.'),
('SQL : ajouter un index sur base chargée', 'Nettoyer un éventuel doublon et surveiller le bloat', TRUE, 4, 'Chaque index est payé à chaque écriture.'),
('SQL : ajouter un index sur base chargée', 'Créer l''index en heure de bureau pour vérifier en direct', FALSE, 5, 'Même CONCURRENTLY ralentit les écritures : le placement compte.'),
('SQL : ajouter un index sur base chargée', 'Désactiver temporairement les autres index', FALSE, 6, 'Aucun lien avec la création et dangereux pour les plans.'),
('SQL : import massif sans casser le service', 'Charger en staging hors ligne (COPY rapide, contraintes relâchées)', TRUE, 1, 'Préparation isolée : aucun impact sur la production pendant le chargement.'),
('SQL : import massif sans casser le service', 'Valider le jeu avant intégration (rejets, doublons, contrôles)', TRUE, 2, 'Intégrer des données non validées déplace le problème en prod.'),
('SQL : import massif sans casser le service', 'Intégrer par lots courts depuis le staging (INSERT SELECT / ATTACH)', TRUE, 3, 'Verrous brefs, service maintenu.'),
('SQL : import massif sans casser le service', 'Vérifier contraintes/index puis ANALYZE des statistiques', TRUE, 4, 'Le planner a besoin de nouvelles stats sur le volume neuf.'),
('SQL : import massif sans casser le service', 'Des INSERT individuels en boucle applicative, la nuit suffit', FALSE, 5, 'Dix fois plus lent qu''un COPY — et nocturne ≠ sûr.'),
('SQL : import massif sans casser le service', 'TRUNCATE puis tout recharger en une transaction', FALSE, 6, 'Risque maximal : indisponibilité totale et point de non-retour.'),
('SQL : doublons bloquant une contrainte UNIQUE', 'Détecter les doublons (requête d''analyse)', TRUE, 1, 'On ne résout pas ce qu''on n''a pas recensé.'),
('SQL : doublons bloquant une contrainte UNIQUE', 'Arbitrage métier : fusionner / conserver le plus récent / corriger la source', TRUE, 2, 'La vraie décision est métier — la technique exécute.'),
('SQL : doublons bloquant une contrainte UNIQUE', 'Appliquer les corrections par lots avec traçabilité', TRUE, 3, 'Auditable et réversible si erreur.'),
('SQL : doublons bloquant une contrainte UNIQUE', 'Créer la contrainte (CONCURRENTLY) une fois la table propre', TRUE, 4, 'La contrainte verrouille maintenant — après nettoyage seulement.'),
('SQL : doublons bloquant une contrainte UNIQUE', 'Ajouter le contrôle applicatif pour éviter les nouveaux doublons', TRUE, 5, 'Prévention : la contrainte seule renverrait des 409 sans guidance.'),
('SQL : doublons bloquant une contrainte UNIQUE', 'Supprimer toutes les lignes dupliquées automatiquement', FALSE, 6, 'Suppression sans arbitrage = perte de données métier.'),
('SQL : purge de colonnes personnelles', 'Cartographier toutes les présences (base, logs, exports, sauvegardes)', TRUE, 1, 'L''oubli d''un dérivé = fuite persistante.'),
('SQL : purge de colonnes personnelles', 'Interrompre flux et exports qui recopient la donnée', TRUE, 2, 'Sinon la donnée se re-copie pendant qu''on efface.'),
('SQL : purge de colonnes personnelles', 'Effacer à la source par lots, avec journal d''exécution', TRUE, 3, 'Traçable et sans verrou long.'),
('SQL : purge de colonnes personnelles', 'Nettoyer les dérivés (logs applicatifs, caches, exports)', TRUE, 4, 'La donnée vit au-delà de la table principale.'),
('SQL : purge de colonnes personnelles', 'VACUUM pour libérer l''espace et rétention des sauvegardes documentée', TRUE, 5, 'Libérer l''espace physique et traiter la rétention des backups.'),
('SQL : purge de colonnes personnelles', 'Effacer uniquement dans la table principale', FALSE, 6, 'Insuffisant : logs/exports/sauvegardes conservent la donnée.'),
('SQL : purge de colonnes personnelles', 'Anonymiser sans jamais rien supprimer', FALSE, 7, 'Valable SI l''anonymisation est irréversible et documentée — le principe prime, pas la forme.')
) AS v(title, content, is_correct, ord, expl)
JOIN challenges c ON c.title = v.title
WHERE NOT EXISTS (SELECT 1 FROM challenge_options o WHERE o.challenge_id = c.id AND o.display_order = v.ord);

